-- 导入心理学 / 摄影 / 烹饪三类参考书 47 本
-- 只上封面与摘要，原 PDF 未上传；has_pdf_source 记录本地是否有 PDF
BEGIN;
-- has_pdf_source 可重复执行
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='catalog' AND table_name='book' AND column_name='has_pdf_source') THEN ALTER TABLE catalog.book ADD COLUMN has_pdf_source boolean DEFAULT false; END IF; END $$;
COMMIT;
